31	template <typename T, typename U, typename S, int M, int K, int N, uint32_t baseM, uint32_t baseK, uint32_t baseN>
32	AICORE inline void ProcessKIteration(
33	    uint32_t kIter, __gm__ U* currentSrc0, __gm__ S* currentSrc1,
34	    Tile<TileType::Mat, U, baseM, baseK, BLayout::ColMajor, baseM, baseK, SLayout::RowMajor> aMatTile[2],
35	    Tile<TileType::Mat, S, baseK, baseN, BLayout::RowMajor, baseK, baseN, SLayout::ColMajor> bMatTile[2],
36	    TileLeft<U, baseM, baseK, baseM, baseK> aTile[2], TileRight<S, baseK, baseN, baseK, baseN> bTile[2],
37	    TileAcc<T, baseM, baseN, baseM, baseN>& cTile)
38	{
39	    using NDValidShapeA = TileShape2D<U, baseM, baseK>;
40	    using NDsingleCoreShapeA = BaseShape2D<U, M, K>;
41	    using GlobalDataSrcA = GlobalTensor<U, NDValidShapeA, NDsingleCoreShapeA>;
42	
43	    using NDValidShapeB = TileShape2D<U, baseK, baseN, Layout::DN>;
44	    using NDsingleCoreShapeB = BaseShape2D<U, K, N, Layout::DN>;
45	    using GlobalDataSrcB = GlobalTensor<U, NDValidShapeB, NDsingleCoreShapeB, Layout::DN>;
46	
47	    int cur = kIter % 2;
48	    GlobalDataSrcA gmA(currentSrc0 + kIter * baseK);
49	    GlobalDataSrcB gmB(currentSrc1 + kIter * baseK);
50	
51	    wait_flag(PIPE_MTE1, PIPE_MTE2, (event_t)cur);
52	    TLOAD(aMatTile[cur], gmA);
53	    set_flag(PIPE_MTE2, PIPE_MTE1, EVENT_ID0);
54	    TLOAD(bMatTile[cur], gmB);
55	    set_flag(PIPE_MTE2, PIPE_MTE1, EVENT_ID1);
56	
57	    wait_flag(PIPE_M, PIPE_MTE1, (event_t)cur);
58	    wait_flag(PIPE_MTE2, PIPE_MTE1, EVENT_ID0);
59	    TMOV(aTile[cur], aMatTile[cur]);
60	    wait_flag(PIPE_MTE2, PIPE_MTE1, EVENT_ID1);
61	    TMOV(bTile[cur], bMatTile[cur]);
62	    set_flag(PIPE_MTE1, PIPE_MTE2, (event_t)cur);
63	
64	    set_flag(PIPE_MTE1, PIPE_M, (event_t)cur);
65	    wait_flag(PIPE_MTE1, PIPE_M, (event_t)cur);
66	    if (kIter == 0) {
67	        TMATMUL(cTile, aTile[cur], bTile[cur]);
68	    } else {
69	        TMATMUL_ACC(cTile, cTile, aTile[cur], bTile[cur]);
70	    }
71	    set_flag(PIPE_M, PIPE_MTE1, (event_t)cur);
72	}
