74	template <
75	    typename T, typename U, typename S, int M, int K, int N, uint32_t singleCoreM, uint32_t singleCoreK,
76	    uint32_t singleCoreN, uint16_t baseM, uint16_t baseK, uint16_t baseN>
77	AICORE inline void runGEMMBASIC(__gm__ T* out, __gm__ U* src0, __gm__ S* src1)
78	{
79	    constexpr uint32_t mIter = M / singleCoreM;
80	    uint32_t mIterIdx = get_block_idx() % mIter;
81	    uint32_t nIterIdx = get_block_idx() / mIter;
82	    uint64_t currentGmOffsetA = mIterIdx * singleCoreM * K;
83	    uint64_t currentGmOffsetB = nIterIdx * K * singleCoreN;
84	    uint64_t currentGmOffsetC = mIterIdx * singleCoreM * N + nIterIdx * singleCoreN;
85	    __gm__ U* currentSrc0 = src0 + currentGmOffsetA;
86	    __gm__ S* currentSrc1 = src1 + currentGmOffsetB;
87	    __gm__ T* currentDst = out + currentGmOffsetC;
88	
89	    using NDValidShapeC = TileShape2D<T, baseM, baseN>;
90	    using NDWholeShapeC = BaseShape2D<T, M, N>;
91	    using GlobalDataOut = GlobalTensor<T, NDValidShapeC, NDWholeShapeC>;
92	
93	    using TileMatAData = Tile<TileType::Mat, U, baseM, baseK, BLayout::ColMajor, baseM, baseK, SLayout::RowMajor>;
94	    using TileMatBData = Tile<TileType::Mat, S, baseK, baseN, BLayout::RowMajor, baseK, baseN, SLayout::ColMajor>;
95	
96	    TileMatAData aMatTile[2];
97	    TileMatBData bMatTile[2];
98	    TASSIGN(aMatTile[0], 0x0);
99	    TASSIGN(aMatTile[1], 0x0 + baseM * baseK * sizeof(U));
100	    TASSIGN(bMatTile[0], 0x0 + baseM * baseK * 2 * sizeof(U));
101	    TASSIGN(bMatTile[1], 0x0 + baseM * baseK * 2 * sizeof(U) + baseK * baseN * sizeof(U));
102	
103	    using LeftTile = TileLeft<U, baseM, baseK, baseM, baseK>;
104	    using RightTile = TileRight<S, baseK, baseN, baseK, baseN>;
105	    using ResTile = TileAcc<T, baseM, baseN, baseM, baseN>;
106	
107	    LeftTile aTile[2];
108	    RightTile bTile[2];
109	    ResTile cTile;
110	    TASSIGN(aTile[0], 0x0);
111	    TASSIGN(aTile[1], 0x0 + baseM * baseK * sizeof(U));
112	    TASSIGN(bTile[0], 0x0);
113	    TASSIGN(bTile[1], 0x0 + baseK * baseN * sizeof(U));
114	    TASSIGN(cTile, 0x0);
115	
116	    constexpr uint32_t kLoop = singleCoreK / baseK;
117	
118	    set_flag(PIPE_MTE1, PIPE_MTE2, EVENT_ID0);
119	    set_flag(PIPE_MTE1, PIPE_MTE2, EVENT_ID1);
120	    set_flag(PIPE_M, PIPE_MTE1, EVENT_ID0);
121	    set_flag(PIPE_M, PIPE_MTE1, EVENT_ID1);
