54	    using TileMatBData = Tile<TileType::Mat, BType, K, N, BLayout::ColMajor, validK, validN, SLayout::RowMajor, 512>;
55	
56	    using LeftTile = TileLeft<AType, M, K, validM, validK>;
57	    using RightTile = TileRight<BType, K, N, validK, validN>;
