183	            reinterpret_cast<int32_t*>(out), reinterpret_cast<int8_t*>(src0), reinterpret_cast<int8_t*>(src1), nullptr);
184	    } else if constexpr (tilingKey == 3) {
185	        RunTMATMUL_SPLIT_K<float, half, half, 128, 128, 64>(
186	            reinterpret_cast<float*>(out), reinterpret_cast<half*>(src0), reinterpret_cast<half*>(src1), 5);
187	    } else if constexpr (tilingKey == 4) {
